import numpy as np, pyreadr
res=pyreadr.read_r('/workspace/Tn5PWM.rds')
pwm=res[None].values.astype(float)  # rows ACGT
bases='ACGT'
def read_fa(path):
    seqs=[]; cur=''
    with open(path) as f:
        for line in f:
            line=line.strip()
            if line.startswith('>'):
                if cur: seqs.append(cur.upper()); cur=''
            else: cur+=line.strip().upper()
    if cur: seqs.append(cur)
    return seqs

def score_window(seq, start, mat):
    s=seq[start:start+mat.shape[1]]
    if len(s)<mat.shape[1]: return None
    sc=0.0
    for i,ch in enumerate(s):
        if ch not in bases: continue
        sc += mat[bases.index(ch),i]
    return sc
# rc pwm rows reverse and reverse columns
rc_pwm=pwm[::-1][:, ::-1]  # rows ACGT reversed? Actually rc: A<->T, C<->G and reverse columns

def mean_scores(path, mat):
    seqs=read_fa(path)
    L=len(seqs[0]); W=mat.shape[1]
    sums=np.zeros(L-W+1); n=0
    for seq in seqs:
        for start in range(L-W+1):
            s=score_window(seq,start,mat)
            if s is not None: sums[start]+=s
        n+=1
    return sums/n
for name,path in [('start','/workspace/start.fa'),('end','/workspace/end.fa')]:
    print('\\n',name,'forward')
    scores=mean_scores(path,pwm)
    for i in range(25,76):
        if 0<=i<len(scores):
            print(i, f'{scores[i]:.3f}')
    print(name,'rc')
    scores=mean_scores(path,rc_pwm)
    for i in range(25,76):
        if 0<=i<len(scores):
            print(i, f'{scores[i]:.3f}')
